USE hms;
ALTER TABLE visits ADD COLUMN IF NOT EXISTS reason VARCHAR(255) NULL;
INSERT IGNORE INTO departments(slug,name,icon,sort) VALUES('general-opd','General OPD','🩺',0),('nbu','NBU (New Born Unit)','👶',22);
CREATE TABLE IF NOT EXISTS nbu_admissions(id INT AUTO_INCREMENT PRIMARY KEY,baby_patient_id INT NOT NULL,mother_patient_id INT NULL,visit_id INT NULL,admitted_at DATETIME DEFAULT CURRENT_TIMESTAMP,birth_at DATETIME NOT NULL,sex VARCHAR(10),gestation_weeks INT,birth_weight_g INT,apgar1 INT,apgar5 INT,apgar10 INT,delivery_mode VARCHAR(30),place_of_birth VARCHAR(40),reason VARCHAR(80),cot_no VARCHAR(10),resp_support VARCHAR(20) DEFAULT 'None',feeding VARCHAR(40),phototherapy TINYINT DEFAULT 0,kmc TINYINT DEFAULT 0,vit_k TINYINT DEFAULT 0,bcg TINYINT DEFAULT 0,opv0 TINYINT DEFAULT 0,hepb TINYINT DEFAULT 0,eye_prophylaxis TINYINT DEFAULT 0,maternal_notes TEXT,status ENUM('admitted','discharged','referred','died') DEFAULT 'admitted',outcome_at DATETIME NULL,discharge_weight_g INT NULL,discharge_notes TEXT,created_by INT) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS nbu_charts(id INT AUTO_INCREMENT PRIMARY KEY,adm_id INT NOT NULL,recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP,temp DECIMAL(4,1),hr INT,rr INT,spo2 INT,weight_g INT,feed_type VARCHAR(30),feed_ml INT,notes VARCHAR(255),nurse_id INT) DEFAULT CHARSET=utf8mb4;
